import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print(0)
        return
    a = [int(x) for x in data[1:n+1]]

    if n < 3:
        print(0)
        return

    min_val = min(a)
    max_val = max(a)

    if min_val == max_val:
        print(0)
        return

    count = 0
    for x in a:
        if min_val < x < max_val:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
